import { useEffect, useRef, useState } from "react";


function Letras({ grosor = 8 }) {
  return (
    <>
      <path d={LADO} className="logo-tinta" />
      <path
        d={B}
        className="logo-puntada"
        fill="none"
        strokeWidth={grosor}
        strokeDasharray={`${grosor * 2.5} ${grosor * 1.75}`}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </>
  );
}


export function LogoCompleto({ animado = false, className = "" }) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);

  // Cada vez que el logo vuelve a la pantalla, se repite el bordado.
  useEffect(() => {
    if (!animado || !ref.current) return;
    const observador = new IntersectionObserver(
      ([entrada]) => setVisible(entrada.isIntersecting),
      { threshold: 0.6 }
    );
    observador.observe(ref.current);
    return () => observador.disconnect();
  }, [animado]);

  const estado = !animado ? "" : visible ? "logo-animado" : "logo-oculto";

  return (
    <svg
      ref={ref}
      className={`logo ${estado} ${className}`}
      viewBox="170 115 935 465"
      role="img"
      aria-label="Lado B, bordando ideas"
    >
      <Letras />
      <path d={HILO} className="logo-hilo" fill="none" strokeWidth="6" strokeLinecap="round" pathLength="1" />
      <line x1="920" y1="480" x2="1084" y2="440" className="logo-aguja" strokeWidth="12" strokeLinecap="round" />
      <ellipse cx="944" cy="474" rx="10" ry="4" className="logo-ojo" transform="rotate(-14 944 474)" />
      <path d={SLOGAN} className="logo-tinta logo-slogan" />
    </svg>
  );
}


export function LogoNombre({ className = "" }) {
  return (
    <svg className={`logo ${className}`} viewBox="176 122 930 254" role="img" aria-label="Lado B">
      <Letras grosor={18} />
    </svg>
  );
}
